class Solution {
    public int[][] insert(int[][] intervals, int[] newInterval) {
        int n = intervals.length;
        int[][] all = new int[n + 1][];
        for (int i = 0; i < n; i++) all[i] = intervals[i];
        all[n] = newInterval;
        Arrays.sort(all, (a, b) -> Integer.compare(a[0], b[0]));
        List<int[]> merged = new ArrayList<>();
        for (int[] cur : all) {
            if (merged.isEmpty() || merged.get(merged.size() - 1)[1] < cur[0]) merged.add(cur);
            else merged.get(merged.size() - 1)[1] = Math.max(merged.get(merged.size() - 1)[1], cur[1]);
        }
        return merged.toArray(new int[merged.size()][]);
    }
}

